16	static uvpolicy_priv_s* policy_uv_init(void)
17	{
18	    uvpolicy_priv_s* priv = malloc(sizeof(*priv));
19	    if (!priv)
20	        return NULL;
21	    memset(priv, 0, sizeof(*priv));
22	
23	    priv->uv_running = false;
24	
25	    priv->loop = (uv_loop_t*)malloc(sizeof(uv_loop_t));
26	    if (!priv->loop) {
27	        syslog(LOG_INFO, "malloc failed %d\n", -errno);
28	        goto fail;
29	    }
30	
31	    if (uv_loop_init(priv->loop) < 0) {
32	        free(priv->loop);
33	        priv->loop = NULL;
34	        goto fail;
35	    }
36	
37	    priv->mutex = (pthread_mutex_t*)malloc(sizeof(pthread_mutex_t));
38	    if (!priv->mutex)
39	        goto fail;
40	    pthread_mutex_init(priv->mutex, NULL);
41	
42	    priv->cond = (pthread_cond_t*)malloc(sizeof(pthread_cond_t));
43	    if (!priv->cond) {
44	        free(priv->mutex);
45	        priv->mutex = NULL;
46	        goto fail;
47	    }
48	    pthread_cond_init(priv->cond, NULL);
49	
50	    return priv;
51	
52	fail:
53	    if (priv->loop) {
54	        /* priv->loop is guaranteed initialized here (uv_loop_init failure
55	         * frees and NULLs it before jumping). EBUSY would mean a handle
56	         * residue — assert so init-failure cleanup does not hide a leak.
57	         */
58	        assert_int_equal(uv_loop_close(priv->loop), 0);
59	        free(priv->loop);
60	        priv->loop = NULL;
61	    }
62	    free(priv);
63	    return NULL;
64	}
65	
66	static void policy_uv_on_close(uv_handle_t *handle)
67	{
68	    syslog(LOG_INFO, "Handle closed: %p", handle);
69	    handle->data = NULL;
70	}
71	// 关闭所有活动句柄的回调函数
72	static void policy_uv_close_active_handle(uv_handle_t *handle, void *arg)
73	{
74	    if (uv_is_active(handle)&& !uv_is_closing(handle)) {
75	        uv_close(handle, policy_uv_on_close);
76	    }
77	}
78	
79	static void policy_uv_deinit(uvpolicy_priv_s** priv_p)
80	{
81	    uvpolicy_priv_s* priv;
82	    if (!priv_p || !*priv_p) {
83	        syslog(LOG_INFO, "policy_uv_deinit: priv is NULL\n");
84	        return;
85	    }
86	    priv = *priv_p;
87	
88	    if (priv->loop) {
89	        // 使用 uv_walk 关闭所有活动句柄
90	        uv_walk(priv->loop, policy_uv_close_active_handle, NULL);
91	
92	        // 确保所有句柄都已关闭
93	        while (uv_loop_alive(priv->loop)) {
94	            uv_run(priv->loop, UV_RUN_NOWAIT);
95	        }
96	        // 关闭 UV 循环 — EBUSY 表示仍有未关闭 handle（UV 残留泄漏），断言 fail
97	        assert_int_equal(uv_loop_close(priv->loop), 0);
98	        free(priv->loop);
99	        priv->loop = NULL;
100	    }
101	
102	    if (priv->str_val)
103	        free(priv->str_val);
104	
105	    pthread_mutex_destroy(priv->mutex);
106	    pthread_cond_destroy(priv->cond);
107	    free(priv->mutex);
108	    free(priv->cond);
109	    free(priv);
110	    *priv_p = NULL;
111	}
