160	/**
161	 * @brief free writing.
162	 *
163	 * Will release only after 2 case are all statisfied:
164	 * 1. uv_write_cb is called, which means write is done.
165	 * 2. received response; or uv_write failed, which means there won't be response.
166	 */
167	static void media_uv_free_writing(MediaWritePriv* writing)
168	{
169	    if (writing && (writing->flags & MEDIA_MSGFLAG_WRITTEN)
170	        && (writing->flags & MEDIA_MSGFLAG_RESPONSED)) {
171	        media_parcel_deinit(&writing->parcel);
172	        free(writing);
173	    }
174	}
175	
176	static MediaWritePriv* media_uv_alloc_writing(int code, const media_parcel* parcel)
177	{
178	    MediaWritePriv* writing;
179	
180	    writing = zalloc(sizeof(MediaWritePriv));
181	    if (!writing)
182	        return NULL;
183	
184	    uv_req_set_data((uv_req_t*)&writing->req, writing);
185	    media_parcel_init(&writing->parcel);
186	    if (parcel)
187	        media_parcel_clone(&writing->parcel, parcel);
188	
189	    writing->parcel.chunk->code = code;
190	    return writing;
191	}
192	
193	static void media_uv_free_pipe(MediaPipePriv* pipe)
194	{
195	    media_parcel_deinit(&pipe->parcel);
196	    free(pipe);
197	}
198	
199	static MediaPipePriv* media_uv_alloc_pipe(MediaProxyPriv* proxy)
200	{
201	    MediaPipePriv* pipe;
202	
203	    pipe = zalloc(sizeof(MediaPipePriv));
204	    if (!pipe)
205	        return NULL;
206	
207	    if (uv_pipe_init(proxy->loop, &pipe->handle, 0) < 0) {
208	        free(pipe);
209	        return NULL;
210	    }
211	
212	    pipe->proxy = proxy;
213	    media_parcel_init(&pipe->parcel);
214	    uv_handle_set_data((uv_handle_t*)&pipe->handle, pipe);
215	    return pipe;
216	}
217	
218	static void media_uv_clear_queue(MediaProxyPriv* proxy)
219	{
220	    MediaWritePriv* writing;
221	
222	    TAILQ_CONCAT(&proxy->sentq, &proxy->pendq, entry);
223	    while ((writing = TAILQ_FIRST(&proxy->sentq))) {
224	        TAILQ_REMOVE(&proxy->sentq, writing, entry);
225	        writing->flags = MEDIA_MSGFLAG_WRITTEN | MEDIA_MSGFLAG_RESPONSED;
226	        media_uv_free_writing(writing);
227	    }
228	}
