230	/**
231	 * @brief free proxy.
232	 *
233	 * Will release only after 3 case are all statisfied:
234	 * 1. Command uv_pipe closed; @see media_uv_read_cb.
235	 * 2. Event uv_pipe closed; @see media_uv_read_cb.
236	 * 3. Called `media_uv_disconnect`.
237	 */
238	static void media_uv_free_proxy(MediaProxyPriv* proxy)
239	{
240	    MEDIA_DEBUG_PROXY(proxy);
241	    if (proxy->cpipe || proxy->epipe)
242	        return; /* Sockets still active. */
243	
244	    if (proxy->flags & MEDIA_PROXYFLAG_DISCONNECT) {
245	        /* Concat 2 queue and clear all. */
246	        media_uv_clear_queue(proxy);
247	        if (proxy->on_release)
248	            proxy->on_release(proxy->cookie, 0);
249	
250	        free(proxy);
251	    }
252	}
253	
254	static void media_uv_close_cb(uv_handle_t* handle)
255	{
256	    MediaPipePriv* pipe = uv_handle_get_data(handle);
257	    MediaProxyPriv* proxy = pipe->proxy;
258	
259	    MEDIA_DEBUG_PROXY(proxy);
260	    if (pipe == proxy->cpipe) {
261	        MEDIA_INFO("close cpipe:%p proxy:%p\n", pipe, proxy);
262	        proxy->cpipe = NULL;
263	    } else if (pipe == proxy->epipe) {
264	        MEDIA_INFO("close epipe:%p proxy:%p\n", pipe, proxy);
265	        proxy->epipe = NULL;
266	    }
267	
268	    media_uv_free_pipe(pipe);
269	    media_uv_free_proxy(proxy);
270	}
271	
272	static void media_uv_close(MediaPipePriv* pipe)
273	{
274	    uv_read_stop((uv_stream_t*)&pipe->handle);
275	    if (!uv_is_closing((uv_handle_t*)&pipe->handle))
276	        uv_close((uv_handle_t*)&pipe->handle, media_uv_close_cb);
277	}
278	
279	static void media_uv_shutdown_cb(uv_shutdown_t* req, int status)
280	{
281	    MediaPipePriv* pipe = uv_req_get_data((uv_req_t*)req);
282	
283	    media_uv_close(pipe);
284	    free(req);
285	}
286	
287	/**
288	 * @brief Shutdown command uv_pipe.
289	 *
290	 * After all `uv_write` is done, posix `shutdown` will be called,
291	 * server will monitor `POLLHUP` and close 2 sockets.
292	 */
293	static void media_uv_shutdown(MediaPipePriv* pipe)
294	{
295	    uv_shutdown_t* req;
296	    int ret;
297	
298	    MEDIA_DEBUG_PROXY(pipe->proxy);
299	    req = zalloc(sizeof(uv_shutdown_t));
300	    if (!req)
301	        return;
302	
303	    uv_req_set_data((uv_req_t*)req, pipe);
304	    ret = uv_shutdown((uv_shutdown_t*)req, (uv_stream_t*)&pipe->handle, media_uv_shutdown_cb);
305	    if (ret < 0) {
306	        MEDIA_ERR_PROXY(pipe->proxy, ret);
307	        media_uv_close(pipe);
308	        free(req);
309	    }
310	}
311	
312	static void media_uv_reconnect_one(MediaProxyPriv* proxy)
313	{
314	    int ret;
315	    MEDIA_DEBUG_PROXY(proxy);
316	
317	    /* Try connect to next cpu. */
318	    proxy->cpu = strtok_r(NULL, MEDIA_CPU_DELIM, &proxy->cpus);
319	    if (!proxy->cpu) {
320	        media_uv_clear_queue(proxy);
321	        proxy->on_connect(proxy->cookie, -ENOENT);
322	        return;
323	    }
324	
325	    if (proxy->cpipe)
326	        media_uv_close(proxy->cpipe);
327	
328	    ret = media_uv_connect_one(proxy);
329	    if (ret < 0)
330	        proxy->on_connect(proxy->cookie, ret);
331	}
332	
333	/**
334	 * @brief Handle connect result.
335	 */
336	static void media_uv_connect_one_cb(uv_connect_t* req, int status)
337	{
338	    MediaPipePriv* pipe = uv_handle_get_data((uv_handle_t*)req->handle);
339	    MediaProxyPriv* proxy = pipe->proxy;
340	    int flags;
341	
342	    MEDIA_DEBUG_PROXY(proxy);
343	    free(req);
344	
345	    /* Cancel the connect on error and user's cancelation */
346	    if (status >= 0 && (proxy->flags & MEDIA_PROXYFLAG_DISCONNECT))
347	        status = -ECANCELED;
348	
349	    if (status < 0) {
350	        MEDIA_ERR_PROXY(proxy, status);
351	        proxy->on_connect(proxy->cookie, status);
352	        media_uv_close(pipe);
353	        return;
354	    }
355	
356	    /* Temp clear flags so that on_connect can always send control message. */
357	    flags = proxy->flags;
358	    proxy->flags = 0;
359	
360	    media_parcel_init(&pipe->parcel);
361	    uv_read_start((uv_stream_t*)&pipe->handle, media_uv_alloc_cb, media_uv_read_cb);
362	    proxy->on_connect(proxy->cookie, status);
363	
364	    /* Restore flags. */
365	    proxy->flags |= flags;
366	}
367	
368	/**
369	 * @brief Try connect once
370	 *
371	 * Try head of server cpu list, the list is kept in `MediaProxyPriv::cpus`.
372	 * Before we receive response:
373	 *  1. avoid shutdown.
374	 *  2. pend all writting except in `MediaProxyPriv::on_connect`.
375	 */
376	static int media_uv_connect_one(MediaProxyPriv* proxy)
377	{
378	    char addr[PATH_MAX];
379	    uv_connect_t* req;
380	    int ret = -ENOMEM;
381	
382	    /* Prepare uv_pipe. */
383	    req = zalloc(sizeof(uv_connect_t));
384	    if (!req)
385	        goto err1;
386	
387	    proxy->cpipe = media_uv_alloc_pipe(proxy);
388	    if (!proxy->cpipe)
389	        goto err2;
390	
391	    /* Connect to media server. */
392	    snprintf(addr, sizeof(addr), MEDIA_SOCKADDR_NAME, proxy->cpu);
393	    proxy->flags |= MEDIA_PROXYFLAG_CONNECTING;
394	    if (!strcmp(proxy->cpu, CONFIG_RPMSG_LOCAL_CPUNAME))
395	        uv_pipe_connect(req, &proxy->cpipe->handle, addr,
396	            media_uv_connect_one_cb);
397	    else {
398	#ifdef CONFIG_NET_RPMSG
399	        uv_pipe_rpmsg_connect(req, &proxy->cpipe->handle, addr, proxy->cpu,
400	            media_uv_connect_one_cb);
401	#else
402	        ret = -ENOSYS;
403	        media_uv_close(proxy->cpipe);
404	        goto err2;
405	#endif
406	    }
407	
408	    MEDIA_INFO("connect cpipe:%p proxy:%p\n", proxy->cpipe, proxy);
409	    MEDIA_DEBUG_PROXY(proxy);
410	    return 0;
411	
412	err2:
413	    free(req);
414	
415	err1:
416	    MEDIA_ERR_PROXY(proxy, ret);
417	    return ret;
418	}
419	
420	static void media_uv_alloc_cb(uv_handle_t* handle,
421	    size_t suggested_size, uv_buf_t* buf)
422	{
423	    MediaPipePriv* pipe = uv_handle_get_data(handle);
424	
425	    buf->base = (char*)pipe->parcel.chunk + pipe->offset;
426	    if (pipe->offset < MEDIA_PARCEL_HEADER_LEN)
427	        buf->len = MEDIA_PARCEL_HEADER_LEN - pipe->offset;
428	    else
429	        buf->len = MEDIA_PARCEL_HEADER_LEN + pipe->parcel.chunk->len - pipe->offset;
430	}
431	
432	static void media_uv_read_cb(uv_stream_t* stream, ssize_t ret,
433	    const uv_buf_t* buf)
434	{
435	    MediaPipePriv* pipe = uv_handle_get_data((uv_handle_t*)stream);
436	
437	    if (ret == 0)
438	        return;
439	
440	    if (ret < 0)
441	        goto err;
442	
443	    pipe->offset += ret;
444	    if (pipe->offset == MEDIA_PARCEL_HEADER_LEN) {
445	        ret = media_parcel_grow(&pipe->parcel, 0, pipe->parcel.chunk->len);
446	        if (ret < 0)
447	            goto err;
448	    }
449	
450	    if (MEDIA_PARCEL_HEADER_LEN + pipe->parcel.chunk->len == pipe->offset) {
451	        ret = media_uv_handle_parcel(pipe);
452	        if (ret < 0)
453	            goto err;
454	
455	        media_parcel_reinit(&pipe->parcel);
456	        pipe->offset = 0;
457	    }
458	
459	    return;
460	
461	err:
462	    if (ret != UV_EOF)
463	        MEDIA_ERR_PROXY(pipe->proxy, (int)ret);
464	
465	    media_uv_close(pipe);
466	}
467	
468	/**
469	 * @brief Handle parcel and flags after on_receive callback
470	 */
471	static int media_uv_handle_parcel(MediaPipePriv* pipe)
472	{
473	    MediaProxyPriv* proxy = pipe->proxy;
474	    MediaWritePriv* writing;
475	
476	    if (pipe == proxy->epipe) {
477	        proxy->on_event(pipe->proxy->cookie, NULL, NULL, &pipe->parcel);
478	        return 0;
479	    }
480	
481	    /* dequeue writing context and notify user. */
482	    writing = media_uv_dequeue_writing(proxy);
483	    assert(writing);
484	    writing->on_receive(proxy->cookie,
485	        writing->cookies[0], writing->cookies[1], &pipe->parcel);
486	    writing->flags |= MEDIA_MSGFLAG_RESPONSED;
487	    media_uv_free_writing(writing);
488	    proxy->nb_recv++;
489	    MEDIA_DEBUG_PROXY(proxy);
490	
491	    /* Handle flags after first on_receive */
492	    if (proxy->flags & MEDIA_PROXYFLAG_CONNECTING) {
493	        proxy->flags &= ~MEDIA_PROXYFLAG_CONNECTING;
494	
495	        if (proxy->flags == MEDIA_PROXYFLAG_LISTENING)
496	            media_uv_listen_one(proxy); /* Might be new flags. */
497	
498	        /* Apply writings if user recognize current proxy */
499	        if (!(proxy->flags & MEDIA_PROXYFLAG_LISTENING)
500	            && !(proxy->flags & MEDIA_PROXYFLAG_RECONNECT))
501	            media_uv_delivery_writing(proxy);
502	
503	        if (proxy->flags & MEDIA_PROXYFLAG_DISCONNECT) {
504	            media_uv_delivery_writing(proxy);
505	            return UV_EOF;
506	        }
507	
508	        if (proxy->flags & MEDIA_PROXYFLAG_RECONNECT) {
509	            proxy->flags &= ~MEDIA_PROXYFLAG_RECONNECT;
510	            media_uv_reconnect_one(proxy);
511	            return UV_EOF;
512	        }
513	    }
514	
515	    return 0;
516	}
517	
518	/**
519	 * @brief Would add writing to sentq on success.
520	 */
521	static void media_uv_write_cb(uv_write_t* req, int status)
522	{
523	    MediaWritePriv* writing = uv_req_get_data((uv_req_t*)req);
524	    MediaProxyPriv* proxy = writing->proxy;
525	
526	    /* Should remove from queue because there won't be response. */
527	    if (status < 0) {
528	        MEDIA_ERR_PROXY(proxy, status);
529	        if (writing->parcel.chunk->code == MEDIA_PARCEL_SEND_ACK) {
530	            TAILQ_REMOVE(&proxy->sentq, writing, entry);
531	            writing->on_receive(proxy->cookie,
532	                writing->cookies[0], writing->cookies[1], NULL);
533	            writing->flags |= MEDIA_MSGFLAG_RESPONSED;
534	        }
535	    } else
536	        proxy->nb_sent++;
537	
538	    /* Should release wiriting because there won't be response. */
539	    writing->flags |= MEDIA_MSGFLAG_WRITTEN;
540	    media_uv_free_writing(writing);
541	}
542	
543	static int media_uv_send_writing(MediaProxyPriv* proxy, MediaWritePriv* writing)
544	{
545	    int ret;
546	    uv_buf_t buf = {
547	        .base = (void*)writing->parcel.chunk,
548	        .len = MEDIA_PARCEL_HEADER_LEN + writing->parcel.chunk->len
549	    };
550	
551	    if (writing->parcel.chunk->code == MEDIA_PARCEL_SEND_ACK) {
552	        /* Move to sentq, and wait for response. */
553	        TAILQ_INSERT_TAIL(&proxy->sentq, writing, entry);
554	        proxy->nb_sentq++;
555	    } else
556	        writing->flags |= MEDIA_MSGFLAG_RESPONSED; /* won't be response. */
557	
558	    MEDIA_DEBUG_PROXY(proxy);
559	    ret = proxy->cpipe
560	        ? uv_write(&writing->req, (uv_stream_t*)&proxy->cpipe->handle,
561	            &buf, 1, media_uv_write_cb)
562	        : -ENOTCONN;
563	    if (ret < 0)
564	        media_uv_write_cb(&writing->req, ret);
565	
566	    MEDIA_DEBUG_PROXY(proxy);
567	    return ret;
568	}
569	
570	/**
571	 * @brief Dequeue and free the head of sentq.
572	 */
573	static MediaWritePriv* media_uv_dequeue_writing(MediaProxyPriv* proxy)
574	{
575	    MediaWritePriv* writing;
576	
577	    writing = TAILQ_FIRST(&proxy->sentq);
578	    if (writing) {
579	        TAILQ_REMOVE(&proxy->sentq, writing, entry);
580	        proxy->nb_sentq--;
581	    }
582	
583	    return writing;
584	}
585	
586	/**
587	 * @brief Write all buffer in pendq, should only call once.
588	 */
589	static void media_uv_delivery_writing(MediaProxyPriv* proxy)
590	{
591	    MediaWritePriv *writing, *tmp;
592	
593	    TAILQ_FOREACH_SAFE(writing, &proxy->pendq, entry, tmp)
594	    {
595	        TAILQ_REMOVE(&proxy->pendq, writing, entry);
596	        proxy->nb_pendq--;
597	        media_uv_send_writing(proxy, writing);
598	    }
599	}
600	
601	/**
602	 * @brief Enqueue writing to pendq or directly write.
603	 */
604	static int media_uv_queue_writing(MediaProxyPriv* proxy, MediaWritePriv* writing)
605	{
606	    writing->proxy = proxy;
607	
608	    if (proxy->flags == 0)
609	        return media_uv_send_writing(proxy, writing);
610	    else {
611	        TAILQ_INSERT_TAIL(&proxy->pendq, writing, entry);
612	        proxy->nb_pendq++;
613	        return 0;
614	    }
615	}
616	
617	static int media_uv_create_notify(MediaProxyPriv* proxy)
618	{
619	    MediaWritePriv* writing;
620	    char addr[PATH_MAX];
621	
622	    writing = media_uv_alloc_writing(MEDIA_PARCEL_CREATE_NOTIFY, NULL);
623	    if (!writing) {
624	        MEDIA_ERR_PROXY(proxy, -ENOMEM);
625	        return -ENOMEM;
626	    }
627	
628	    snprintf(addr, sizeof(addr), "md_%p", proxy);
629	    media_parcel_append_printf(&writing->parcel, "%s%s", addr, CONFIG_RPMSG_LOCAL_CPUNAME);
630	    writing->proxy = proxy;
631	    return media_uv_send_writing(proxy, writing);
632	}
633	
634	static void media_uv_listen_one_cb(uv_stream_t* stream, int ret)
635	{
636	    MediaPipePriv* server = uv_handle_get_data((uv_handle_t*)stream);
637	    MediaProxyPriv* proxy = server->proxy;
638	
639	    proxy->flags &= ~MEDIA_PROXYFLAG_LISTENING;
640	
641	    /* Handle error and user's cancelation. */
642	    if (ret < 0)
643	        goto err1;
644	
645	    if (proxy->flags & MEDIA_PROXYFLAG_DISCONNECT) {
646	        ret = -ECANCELED;
647	        goto err1;
648	    }
649	
650	    /* Prepare client stream and take place of server stream. */
651	    proxy->epipe = media_uv_alloc_pipe(proxy);
652	    if (!proxy->epipe)
653	        goto err1;
654	
655	    ret = uv_accept(stream, (uv_stream_t*)&proxy->epipe->handle);
656	    if (ret < 0)
657	        goto err2;
658	
659	    MEDIA_INFO("connect epipe:%p proxy:%p\n", proxy->epipe, proxy);
660	    media_uv_close(server);
661	    MEDIA_DEBUG_PROXY(proxy);
662	    if (proxy->on_listen)
663	        proxy->on_listen(proxy->cookie, ret);
664	    media_uv_delivery_writing(proxy);
665	    uv_read_start((uv_stream_t*)&proxy->epipe->handle, media_uv_alloc_cb, media_uv_read_cb);
666	    return;
667	
668	err2:
669	    media_uv_close(proxy->epipe);
670	
671	err1:
672	    media_uv_close(server);
673	    MEDIA_ERR_PROXY(proxy, ret);
674	    if (proxy->on_listen)
675	        proxy->on_listen(proxy->cookie, ret);
676	}
677	
678	/**
679	 * @brief Do real work of creating listener.
680	 */
681	static int media_uv_listen_one(MediaProxyPriv* proxy)
682	{
683	    char addr[PATH_MAX];
684	    int ret = -ENOMEM;
685	
686	    /* Prepare server stream. */
687	    proxy->epipe = media_uv_alloc_pipe(proxy);
688	    if (!proxy->epipe)
689	        goto err1;
690	
691	    snprintf(addr, sizeof(addr), "md_%p", proxy);
692	    if (!strcmp(proxy->cpu, CONFIG_RPMSG_LOCAL_CPUNAME))
693	        ret = uv_pipe_bind(&proxy->epipe->handle, addr);
694	    else
695	#ifdef CONFIG_NET_RPMSG
696	        ret = uv_pipe_rpmsg_bind(&proxy->epipe->handle, addr, proxy->cpu);
697	#else
698	        ret = -ENOSYS;
699	#endif
700	    if (ret < 0)
701	        goto err2;
702	
703	    ret = uv_listen((uv_stream_t*)&proxy->epipe->handle, 1, media_uv_listen_one_cb);
704	    if (ret < 0)
705	        goto err2;
706	
707	    /* Notify media server to back connect. */
708	    ret = media_uv_create_notify(proxy);
709	    if (ret < 0)
710	        goto err2;
711	
712	    proxy->flags |= MEDIA_PROXYFLAG_LISTENING;
713	    MEDIA_DEBUG_PROXY(proxy);
714	    return ret;
715	
716	err2:
717	    media_uv_close(proxy->epipe);
718	
719	err1:
720	    MEDIA_ERR_PROXY(proxy, ret);
721	    if (proxy->on_listen)
722	        proxy->on_listen(proxy->cookie, ret);
723	
724	    return ret;
725	}
