727	/****************************************************************************
728	 * Public Functions
729	 ****************************************************************************/
730	
731	void* media_uv_connect(void* loop, const char* cpus,
732	    media_uv_callback on_connect, void* cookie)
733	{
734	    MediaProxyPriv* proxy;
735	    int ret = -ENOMEM;
736	
737	    if (!cpus || !loop || !on_connect) {
738	        ret = -EINVAL;
739	        goto err1;
740	    }
741	
742	    proxy = zalloc(sizeof(MediaProxyPriv) + strlen(cpus) + 1);
743	    if (!proxy)
744	        goto err1;
745	
746	    proxy->loop = loop;
747	    proxy->cookie = cookie;
748	    proxy->on_connect = on_connect;
749	    TAILQ_INIT(&proxy->pendq);
750	    TAILQ_INIT(&proxy->sentq);
751	    proxy->cpus = (char*)(proxy + 1);
752	    strcpy(proxy->cpus, cpus);
753	    proxy->cpu = strtok_r(proxy->cpus, MEDIA_CPU_DELIM, &proxy->cpus);
754	    if (!proxy->cpu)
755	        goto err2;
756	
757	    MEDIA_DEBUG("%s:%p cookie:%p\n", cpus, proxy, cookie);
758	    ret = media_uv_connect_one(proxy);
759	    if (ret < 0)
760	        goto err2;
761	
762	    return proxy;
763	
764	err2:
765	    free(proxy);
766	
767	err1:
768	    MEDIA_ERR("err:%d\n", ret);
769	    return NULL;
770	}
771	
772	int media_uv_disconnect(void* handle, media_uv_callback on_release)
773	{
774	    MediaProxyPriv* proxy = handle;
775	
776	    if (!proxy || (proxy->flags & MEDIA_PROXYFLAG_DISCONNECT))
777	        return -EINVAL;
778	
779	    proxy->on_release = on_release;
780	
781	    if (proxy->flags == 0 && proxy->cpipe) /* Needn't shutdown command socket if not ready. */
782	        media_uv_shutdown(proxy->cpipe);
783	    else
784	        MEDIA_INFO("disconnect proxy:%p flags:%d cpipe:%p epipe:%p"
785	                   " pendq:%d sentq:%d nb_sent:%d nb_recv:%d\n",
786	            proxy, proxy->flags, proxy->cpipe, proxy->epipe,
787	            proxy->nb_pendq, proxy->nb_sentq, proxy->nb_sent, proxy->nb_recv);
788	
789	    proxy->flags |= MEDIA_PROXYFLAG_DISCONNECT;
790	    media_uv_free_proxy(proxy); /* Do real work if uv_pipes already closed. */
791	    return 0;
792	}
793	
794	int media_uv_reconnect(void* handle)
795	{
796	    MediaProxyPriv* proxy = handle;
797	
798	    if (!proxy || proxy->epipe)
799	        return -EINVAL; /* Cannot reconnect if listener created. */
800	
801	    if (proxy->flags == 0)
802	        media_uv_reconnect_one(proxy);
803	    else
804	        proxy->flags |= MEDIA_PROXYFLAG_RECONNECT;
805	
806	    /* Notify reconnect result by on_connect callback. */
807	    return 0;
808	}
809	
810	int media_uv_listen(void* handle, media_uv_callback on_listen,
811	    media_uv_parcel_callback on_event)
812	{
813	    MediaProxyPriv* proxy = handle;
814	    int ret = 0;
815	
816	    if (!proxy || !on_event)
817	        return -EINVAL;
818	
819	    if ((proxy->flags & MEDIA_PROXYFLAG_LISTENING) || proxy->epipe) {
820	        ret = -EPERM; /* Cannot create another listener. */
821	        goto err;
822	    }
823	
824	    proxy->on_listen = on_listen;
825	    proxy->on_event = on_event;
826	
827	    /* Directly do real work if proxy is working. */
828	    if (proxy->flags == 0)
829	        ret = media_uv_listen_one(proxy);
830	    else /* Set flag and do nothing if there are reconnect/disconnect to do. */
831	        proxy->flags |= MEDIA_PROXYFLAG_LISTENING;
832	
833	    return ret;
834	
835	err:
836	    MEDIA_ERR_PROXY(proxy, ret);
837	    return ret;
838	}
839	
840	int media_uv_send(void* handle, media_uv_parcel_callback on_receive,
841	    void* cookie0, void* cookie1, const media_parcel* parcel)
842	{
843	    MediaProxyPriv* proxy = handle;
844	    MediaWritePriv* writing;
845	    int ret;
846	
847	    if (!proxy)
848	        return -EINVAL;
849	
850	    if (!proxy->cpu) {
