51	static ssize_t test_player_process_data(int fd, bool player,
52	    void *data, size_t len)
53	{
54	    int event = player ? POLLOUT : POLLIN;
55	    struct pollfd fds[1];
56	    int ret;
57	
58	    fds[0].fd = fd;
59	    fds[0].events = event;
60	    ret = poll(fds, 1, 3000);
61	
62	    if (ret < 0)
63	        return -errno;
64	
65	    if (player)
66	        return send(fd, data, len, 0);
67	    else
68	        return recv(fd, data, len, 0);
69	}
