71	void audio_config_init_internal(audio_desc_t *priv, audio_config_t config, int planar)
72	{
73	    struct sin_desc *s_desc = &priv->sin_desc;
74	
75	    priv->is_planar = planar;
76	    params_mapping(priv, config);
77	
