83	void *test_reconfig_buffer_mode_write_thread(void *arg)
84	{
85	    struct test_reconfig_buffer_mode_state_s *priv = (struct test_reconfig_buffer_mode_state_s *)arg;
86	    struct audio_desc *a_desc = &priv->audio_desc;
87	
88	    signed short *buffer = NULL;
89	    char* buf_ptr = NULL;
90	    int act, ret;
91	    int fd = 0, block_fd = 0;
92	    double phase = 0;
93	    int period_size = a_desc->rate / 1000 * 20;
94	    int duration;
95	
96	    duration = (priv->duration > 0) ? priv->duration : TEST_RECONFIG_BUFFER_MODE_DURATION;
97	
98	    block_fd = media_player_get_socket(priv->player);
99	    if (block_fd < 0)
100	        goto out;
101	
102	    act = period_size * a_desc->channels * sizeof(signed short);
103	    buffer = malloc(act);
104	    if (!buffer)
105	        goto out;
106	
107	    syslog(LOG_INFO, "%s, start, line %d %p %d\n", __func__, __LINE__, priv->player, block_fd);
108	
109	    time_t start_time = time(NULL);
110	
111	    while (1) {
112	        if (difftime(time(NULL), start_time) >= duration) {
113	            printf("Test duration reached: %d seconds\n", duration);
114	            break;
115	        }
116	
117	        act = period_size * a_desc->channels * sizeof(signed short);
118	
119	        generate_drumbeat(buffer, period_size, &phase, a_desc);
120	        buf_ptr = (char *)buffer;
121	        while (act > 0) {
122	            ret = test_player_process_data(block_fd, true, buf_ptr, act);
123	            if (ret == 0) {
124	                break;
125	            } else if (ret < 0 && errno == EAGAIN) {
126	                usleep(1000);
127	                continue;
128	            } else if (ret < 0) {
129	                syslog(LOG_ERR, "%s, error ret %d errno %d, line %d\n", __func__, ret, errno, __LINE__);
130	                goto out;
131	            }
132	
133	            buf_ptr += ret;
134	            act -= ret;
135	        }
136	    }
137	out:
138	    media_player_close_socket(priv->player);
139	    if (buffer != NULL) {
140	        free(buffer);
141	        buffer = NULL;
142	    }
143	
144	    if (fd < 0) {
145	        close(fd);
146	        fd = 0;
147	    }
148	
149	    if (block_fd < 0) {
150	        return (void *)(int)-1;
151	    }
152	
153	    return (void *)(int)ret;
154	}
