199	int policy_uv_setup(FAR void** state)
200	{
201	    uvpolicy_priv_s* priv = policy_uv_init();
202	    assert_non_null(priv);
203	
204	    pthread_attr_t attr;
205	    pthread_attr_init(&attr);
206	    pthread_attr_setstacksize(&attr, 80 * 1024);
207	    pthread_create(&priv->thread, &attr, policy_uvloop_thread, priv);
208	
209	    pthread_mutex_lock(priv->mutex);
210	    while (!priv->uv_running) {
211	        pthread_cond_wait(priv->cond, priv->mutex);
212	    }
213	    pthread_mutex_unlock(priv->mutex);
214	
215	    *state = priv;
216	    return 0;
217	}
218	
219	int policy_uv_teardown(FAR void** state)
220	{
221	    uvpolicy_priv_s* priv = *state;
222	
223	    if (!priv) {
224	        syslog(LOG_INFO, "policy_uv_teardown: priv is NULL\n");
225	        return 0;
226	    }
227	
228	    uv_async_queue_send(&priv->async_queue, (void*)(intptr_t){POLICY_UV_ASYNCQ_EXIT_CMD});
229	    syslog(LOG_INFO, "before close lock\n");
230	    sleep(1);
231	
232	    pthread_mutex_lock(priv->mutex);
233	    priv->uv_running = false;
234	    pthread_cond_signal(priv->cond);
235	    pthread_mutex_unlock(priv->mutex);
236	
237	    pthread_join(priv->thread, NULL);
238	    policy_uv_deinit(&priv);
239	    *state = NULL;
240	    return 0;
241	}
