63	void *media_buffer_thread(void *arg)
64	{
65	    struct media_s *media = arg;
66	    ssize_t act, ret;
67	    int fd = 0;
68	    char *tmp;
69	
70	    printf("%s, start, line %d\n", __func__, __LINE__);
71	
72	    if (media->direct)
73	    {
74	        if (media->type == PLAYER)
75	            fd = media_player_get_socket(media->handle);
76	        else
77	            fd = media_recorder_get_socket(media->handle);
78	
79	        if (fd < 0)
80	            return NULL;
81	
82	        if (fcntl(fd, F_SETFL, fcntl(fd, F_GETFL, 0) | O_NONBLOCK) < 0)
83	            return NULL;
84	    }
85	
86	    if (media->type == PLAYER)
87	    {
88	        while (1)
89	        {
90	            act = read(media->fd, media->buf, media->size);
91	            if (act == 0)
92	            {
93	                media_player_close_socket(media->handle);
94	                break;
95	            }
96	
97	            tmp = media->buf;
98	            while (act > 0)
99	            {
100	                if (media->direct)
101	                {
102	                    ret = media_process_data(fd, true, tmp, act);
103	                }
104	                else
105	                {
106	                    ret = media_player_write_data(media->handle, tmp, act);
107	                }
108	
109	                if (ret == 0)
110	                {
111	                    break;
112	                }
113	                else if (ret < 0 && errno == EAGAIN)
114	                {
115	                    continue;
116	                }
117	                else if (ret < 0)
118	                {
119	                    printf("%s, error ret %d errno %d, line %d\n", __func__, ret, errno, __LINE__);
120	                    goto out;
121	                }
122	
123	                tmp += ret;
124	                if (act >= ret)
125	                  act -= ret;
126	                else {
127	                  perror("Variable overflowed");
128	                  return NULL;
129	                }
130	            }
131	        }
132	    }
133	    else
134	    {
135	        while (1)
136	        {
137	            if (media->direct)
138	                ret = media_process_data(fd, false, media->buf, media->size);
139	            else
140	                ret = media_recorder_read_data(media->handle, media->buf, media->size);
141	
142	            if (ret == 0)
143	            {
144	                media_recorder_close_socket(media->handle);
145	                break;
146	            }
147	            else if (ret < 0 && errno == EAGAIN)
148	            {
149	                continue;
150	            }
151	            else if (ret < 0)
152	            {
153	                goto out;
154	            }
155	
156	            act = write(media->fd, media->buf, ret);
157	        }
158	    }
159	out:
160	    printf("%s, end, line %d\n", __func__, __LINE__);
161	    return NULL;
162	}
